    <li className={isBoss ? "enemy-item boss" : "enemy-item"}>
      <div className="enemy-name">{name}</div>
      <div className="enemy-meta">
        <span className="enemy-type">{type}</span>
        <span className="enemy-hp">HP: {hp}</span>
        {isBoss && <span className="enemy-badge">Boss</span>}
      </div>
    </li>
  );
}
export default EnemyItem;
```

