```jsx
function EnemyFetcher({ mode, query, onAddEnemy }) {
  const [enemies, setEnemies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    async function fetchEnemies() {
      setLoading(true);
      setError(null);
      try {
        const encodedQuery = encodeURIComponent(query || "");
        const response = await fetch(
          `https://jsonplaceholder.typicode.com/todos?mode=${mode}&q=${encodedQuery}`
        );
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const json = await response.json();
        setEnemies(json);
      } catch (err) {
        setError(err);
      } finally {
        setLoading(false);
      }
    }
    fetchEnemies();
  }, [mode, query]);

  if (loading) return <div>Loading enemies...</div>;
  if (error) return <div>Failed to load enemies. Please try again later.</div>;
  if (enemies.length === 0) return <div>No enemies yet. Spawn some!</div>;

  return (
    <div>
      <EnemySpawnerForm onSpawnEnemy={onAddEnemy} />
      <EnemyList enemies={enemies} />
    </div>
  );
}
